const pluginCatalog=[{id:'github',name:'GitHub',version:'0.3.0',icon:'github',color:'',category:'developer',summary:'Your repositories, reviews and CI, right where your day begins.',source:'onetest-ai/echo-plugins',capabilities:[['key','Use your GitHub sign-in','Read the GitHub CLI or git sign-in on this computer, or keep this plugin’s sign-in.'],['globe','Connect to GitHub','Only github.com and api.github.com.'],['list','Bring GitHub items to your workspace','Add reviews, issues and work rows to Today and spaces.'],['spark','Provide session hints','Make selected repository context available in AI sessions.']],contributes:['3 Today widgets','Work rows','Space sources','Plugin settings','Agent context'],needs:'Echo API ≥0.9.9'},
{id:'obsidian',name:'Obsidian',version:'0.8.0',icon:'gem',color:'',category:'knowledge',summary:'Your local Markdown vault, connected to the rest of your workspace.',source:'onetest-ai/echo-plugins',capabilities:[['folder','Read folders you choose','Only Obsidian vaults explicitly selected by you.'],['spark','Run Claude on your AI profile','Use your chosen Claude Code profile under the host’s session rules.'],['book','Read workspace context','Clients, threads, dictionary and sources; may add dictionary entries.'],['automation','Extend AI sessions','Provide skills, read grants, hints and declared search commands.']],contributes:['Knowledge views','Vault settings','Session skills','Agent context','Dictionary entries'],needs:'Echo API ≥0.9.9'},
{id:'scheduler',name:'Scheduler',version:'0.4.0',icon:'automation',color:'green',category:'automation',summary:'Your own prompts on a schedule. Morning briefs, reflections and useful routines.',source:'onetest-ai/echo-plugins',capabilities:[['spark','Run Claude on your AI profile','Use a selected profile; retain host approval and action rules.'],['clock','Work on a schedule','Runs while the native host is running, including in the background.'],['mail','Deliver results to you','Today, Teams, mail and Telegram, when those destinations are configured.']],contributes:['Automations page','Scheduled prompts','Command palette','Result history'],needs:'Echo API ≥0.9.9'},
{id:'telegram',name:'Telegram',version:'0.4.0',icon:'telegram',color:'blue',category:'chat',summary:'Continue your workspace conversation through your own Telegram bot.',source:'onetest-ai/echo-plugins',capabilities:[['telegram','Provide Telegram delivery','Other approved routines can send to your configured Telegram destination.'],['globe','Connect to Telegram','Only api.telegram.org.'],['puzzle','Install a Claude Code channel','telegram@claude-plugins-official in your default AI profile.']],contributes:['Telegram channel','Delivery destination','Bot settings'],needs:'Echo API ≥0.9.9'},
{id:'focus-card',name:'Focus card',version:'0.1.0',icon:'heart',color:'peach',category:'personal',summary:'A small example you can make your own. One native-looking widget, no network.',source:'My plugins',capabilities:[],contributes:['Today widget','Agent guide'],needs:'Echo-format starter · validation pending'},
{id:'desktop-actions',name:'Desktop actions',version:'0.1.0',icon:'monitor',color:'blue',category:'desktop',summary:'A concept for shortcuts and desktop automation. Requires a new host capability.',source:'Concepts',capabilities:[['monitor','Desktop control','Proposed desktop_control capability. Not part of the inspected Echo API.']],contributes:['Desktop shortcuts','Command palette'],needs:'Unavailable · host extension required',unsupported:true}];
function pluginById(){return pluginCatalog.find(p=>p.id===new URLSearchParams(location.search).get('id'))||pluginCatalog[0]}
function pluginInstalled(id){return !!state.plugins[id]?.installed}
function pluginEnabled(id){return !!state.plugins[id]?.enabled}
function pluginBadge(p){if(p.unsupported)return tag('HOST EXTENSION NEEDED','amber');if(pluginInstalled(p.id))return tag(pluginEnabled(p.id)?'Installed':'Disabled',pluginEnabled(p.id)?'green':'');return tag(p.source==='My plugins'?'YOUR STARTER':'ECHO PACKAGE',p.source==='My plugins'?'blue':'purple')}
function pluginCard(p){return `<article class="panel catalog-card" data-plugin-id="${p.id}"><div class="between"><a href="plugin.html?id=${p.id}" class="plugin-icon ${p.color}" aria-label="Open ${p.name}">${icon(p.icon)}</a>${pluginBadge(p)}</div><h3><a href="plugin.html?id=${p.id}">${p.name}</a></h3><p>${p.summary}</p><div class="card-bottom"><span class="dim" style="font-size:10px">${p.source==='My plugins'?'Your local plugin':'v'+p.version+' · '+(p.unsupported?'Concept':'Echo ≥0.9.9')}</span>${linkBtn(pluginInstalled(p.id)?'Manage':p.unsupported?'Requirements':'Explore','plugin.html?id='+p.id,'chevron','sm')}</div></article>`}
pages.plugins=()=>{const tab=new URLSearchParams(location.search).get('tab')||'discover';let list=pluginCatalog.filter(p=>(tab!=='installed'||pluginInstalled(p.id))&&(state.pluginFilter==='all'||p.category===state.pluginFilter)&&(!state.pluginSearch||(p.name+' '+p.summary).toLowerCase().includes(state.pluginSearch.toLowerCase())));return `${head('Plugins','Add the capabilities that make this workspace yours.',linkBtn('Developer studio','plugin-studio.html','code')+btn('Add plugin','add-plugin','plus','primary'))}<nav class="tabs">${[['discover','Discover'],['installed','Installed'],['updates','Updates'],['marketplaces','Marketplaces']].map(([id,t])=>`<a class="tab ${tab===id?'active':''}" href="plugins.html?tab=${id}">${t}${id==='updates'?tag('1','purple'):''}</a>`).join('')}</nav>${tab==='marketplaces'?marketplacesView():tab==='updates'?pluginUpdatesView():`<div class="plugin-feature"><div class="plugin-icon">${icon('puzzle')}</div><div class="grow"><div class="kicker accent">OPEN BY DESIGN</div><h2>Your workspace can grow with you.</h2><p>Discover Echo-format packages, add a private marketplace, or build your own. One package contract, with capabilities checked by each host.</p></div><a class="text-link small" href="plugin-studio.html">Build a plugin ${icon('arrow')}</a></div><div class="toolbar"><div class="search-field">${icon('search')}<input id="plugin-search" type="search" placeholder="Search plugins…" value="${esc(state.pluginSearch)}" aria-label="Search plugins"></div><select id="plugin-category" aria-label="Plugin category">${[['all','All capabilities'],['knowledge','Knowledge'],['automation','Automation'],['developer','Developer'],['chat','Communication'],['personal','Personal'],['desktop','Desktop']].map(([v,t])=>`<option value="${v}" ${state.pluginFilter===v?'selected':''}>${t}</option>`).join('')}</select><span class="grow"></span><span class="small dim">${list.length} packages</span></div><div class="grid3" id="plugin-grid">${list.map(pluginCard).join('')}</div>${!list.length?empty('No matching plugins','Try a broader search, another category, or add a marketplace.',btn('Clear filters','clear-plugin-search','refresh'),'search'):''}`}<div class="notice mt"><strong>Compatibility is a planned host feature.</strong> These sample installs demonstrate the experience. Connect does not currently execute Echo plugins. The native adapter must pass package, service and UI conformance checks before showing a verified badge. <a class="text-link" href="docs/PLUGIN-REUSE.md">Read the investigation</a></div>`};
function marketplacesView(){return `<div class="between mb"><div><h2>Your marketplaces</h2><p class="small">Public catalogs, a team repository or a folder you own.</p></div>${btn('Add marketplace','add-marketplace','plus','primary')}</div><div class="panel">${state.marketplaces.map((m,i)=>settingRow(esc(m),i===0?'4 packages · Catalog format: echo-marketplace.json':'Custom catalog · pending native validation',`<div class="flex">${tag(i===0?'Default':'Custom',i===0?'purple':'')}${btn('Refresh',`refresh-marketplace:${i}`,'refresh','sm')}${i>0?btn('Remove',`remove-marketplace:${i}`,'trash','ghost sm'):''}</div>`)).join('')}${settingRow('My plugins','Your own local packages. Keep development separate from marketplace versions.',linkBtn('Open studio','plugin-studio.html','code','sm'))}</div><div class="notice mt">The native host will resolve a catalog to a commit, validate the package tree, and record the installed content hash. A custom catalog is another source of trusted code, not an automatic permission grant.</div>`}
function pluginUpdatesView(){return `<div class="panel panel-pad"><div class="flex"><div class="plugin-icon">${icon('github')}</div><div class="grow"><h3>GitHub</h3><p class="small">0.3.0 → 0.3.1 · Illustrative update scenario</p></div>${tag(state.pluginUpdated?'Updated':'Permission review',state.pluginUpdated?'green':'amber')}</div><p class="small mt">The sample update listens for source changes so it can refresh its workspace context. Review the new permission before updating.</p><div class="notice amber mt"><strong>New access:</strong> Hear the <span class="mono">sources_changed</span> event. Existing GitHub network and sign-in permissions remain listed on the review sheet.</div><div class="mt">${btn(state.pluginUpdated?'View installed plugin':'Review update',state.pluginUpdated?'open-github':'review-plugin-update','shield','primary')}</div></div>`}
pages.plugin=()=>{const p=pluginById();return `${head('','',linkBtn('All plugins','plugins.html','back','ghost'),'PLUGINS / '+p.category.toUpperCase())}<div class="plugin-detail-head"><div class="plugin-icon ${p.color}">${icon(p.icon)}</div><div class="grow"><h1>${p.name}</h1><div class="flex wrap small dim"><span>v${state.plugins[p.id]?.version||p.version}</span><span>·</span><span>${p.source}</span><span>·</span>${pluginBadge(p)}</div></div>${p.unsupported?btn('View host requirement','unsupported-plugin','info'):pluginInstalled(p.id)?`<div class="flex">${btn(pluginEnabled(p.id)?'Disable':'Enable',`toggle-plugin:${p.id}`,'puzzle')}${btn('Remove',`remove-plugin:${p.id}`,'trash','ghost')}</div>`:btn('Install plugin',`install-plugin:${p.id}`,'download','primary')}</div><p style="font-size:14px;max-width:750px;margin-bottom:25px">${p.summary}</p><nav class="tabs">${[['overview','Overview'],['settings','Settings'],['permissions','Permissions'],['compatibility','Compatibility']].map(([id,t])=>`<button class="tab ${transient.pluginTab===id?'active':''}" data-action="plugin-tab:${id}">${t}</button>`).join('')}</nav><div class="two-column"><div>${pluginDetailContent(p)}</div><aside class="stack">${panel('At a glance',`<div class="panel-pad" style="padding-top:0"><div class="small dim">PACKAGE CONTRACT</div><p class="small" style="margin:6px 0 16px">${p.needs}</p><div class="small dim">APPEARS IN</div><div class="flex wrap" style="margin:8px 0 18px">${p.contributes.map(c=>`<span class="chip">${c}</span>`).join('')}</div><div class="small dim">INSTALL LOCATION</div><p class="small" style="margin-top:6px">Isolated workspace package and store</p></div>`,'','puzzle')}<div class="notice"><strong>Same package. Explicit support.</strong> An Echo package keeps its original manifest and code. The host must implement every service it uses before enabling it.</div></aside></div>`};
function pluginDetailContent(p){if(transient.pluginTab==='permissions')return `<div class="panel panel-pad"><h2>Declared access</h2><p class="small mt">Generated from this package’s manifest, in the host’s own words.</p>${permissionsHtml(p)}<div class="notice amber">Installing a plugin means trusting its code. Client JavaScript and declared scripts are not an OS sandbox. Review both publisher and permissions.</div></div>`;if(transient.pluginTab==='compatibility')return `<div class="panel panel-pad"><h2>Compatibility report</h2><p class="small mt">Source inspection of the Echo 0.9.9 contract. Native runtime tests have not been run in Connect.</p><div class="line"></div>${[['Manifest','echo-plugin.json kept unchanged'],['Host code','main.js → apply(ctx) in embedded QuickJS'],['UI code','client.js → Echo-compatible slots and helpers'],['Data','Workspace-owned stores, grants and stable thread IDs'],['AI','Claude runs on a selected direct or CodeMie profile']].map(([t,d])=>settingRow(t,d,tag(p.unsupported?'Missing capability':'Planned',p.unsupported?'amber':''))).join('')}<div class="notice ${p.unsupported?'amber':''} mt"><strong>${p.unsupported?'Blocked: desktop_control is not in the inspected Echo API.':'Target: unchanged package reuse.'}</strong> ${p.unsupported?'Design and implement the capability in both hosts or keep this package host-specific.':'Shared contract tests and actual cross-host runs are required before compatibility is verified.'}</div></div>`;if(transient.pluginTab==='settings')return pluginSettings(p);return `<div class="panel panel-pad"><div class="kicker accent">WHAT IT BRINGS TO YOUR DAY</div><h2 style="font-size:23px;margin:12px 0 20px">${{github:'A useful glance, without another tab.',obsidian:'Knowledge that belongs to you.',scheduler:'A routine that knows your context.',telegram:'Your workspace, a message away.','focus-card':'Start small. Make it yours.','desktop-actions':'Desktop capabilities, by explicit design.'}[p.id]}</h2>${p.contributes.slice(0,3).map((c,i)=>`<div class="feature-row"><span class="round-icon ${p.color}">${icon([p.icon,'spark','settings'][i])}</span><div><h3>${c}</h3><p>${i===0?p.summary:i===1?'Use the profile and context you choose. Your direct Claude account works without CodeMie.':'Control what is enabled and where it appears in your workspace.'}</p></div></div>`).join('')}<div class="line"></div>${p.id==='github'?`<div class="between"><div class="widget-heading">${icon('github')} Sample widget</div>${tag('TODAY','purple')}</div><div class="widget-number" style="font-size:28px;margin:15px 0">2 <span class="small muted">reviews waiting</span></div><div class="list-row" style="padding-left:0"><span class="success">${icon('check')}</span><span class="grow small">workspace / connect</span>${tag('CI passing','green')}</div>${btn('Add to Today','add-github-widget','plus','sm')}`:p.id==='scheduler'?linkBtn('Open Automations','automations.html','automation','primary'):p.id==='obsidian'?linkBtn('Open Knowledge','knowledge.html','book','primary'):p.id==='focus-card'?`<p class="small mb">An original sample package is included under examples/focus-card. It uses the Echo manifest and a simple card widget.</p><a class="btn" href="examples/focus-card.zip" download>${icon('download')}Download starter package</a>`:p.id==='telegram'?btn('Configure bot','configure-telegram','telegram','primary'):btn('Inspect missing capability','unsupported-plugin','info')}</div>`}
function permissionsHtml(p){return p.capabilities.length?`<ul class="permission-list">${p.capabilities.map(([i,t,d])=>`<li>${icon(i)}<div><strong>${t}</strong><p>${d}</p></div></li>`).join('')}</ul>`:'<div class="notice green mt mb"><strong>No additional access requested.</strong> This starter provides a static widget and agent reference. It does not use files, network, AI runs or scripts.</div>'}
function pluginSettings(p){if(!pluginInstalled(p.id))return `<div class="panel">${empty('Make it part of your workspace','Install the plugin after reviewing its access, then choose how it works for you.',p.unsupported?btn('View requirement','unsupported-plugin','info'):btn('Review & install',`install-plugin:${p.id}`,'download','primary'),'puzzle')}</div>`;if(p.id==='github')return `<div class="panel">${settingRow('GitHub account','Demo account · existing GitHub CLI sign-in. No token is shown.',btn('Change account','github-signin','key','sm'))}${settingRow('Selected repositories',state.githubRepos||'workspace/connect, workspace/notes',btn('Choose repositories','github-repos','plus','sm'))}${settingRow('Show pull requests','Include open requests in the plugin’s widget.',toggle('githubPRs','Show pull requests',state.githubPRs!==false))}${settingRow('Show CI status','An at-a-glance view of selected repositories.',toggle('githubCI','Show CI status',state.githubCI!==false))}${settingRow('Refresh data','The native plugin fetches in the background; Today reads cached widget data.',btn('Refresh now','github-refresh','refresh','sm'))}</div>`;if(p.id==='obsidian')return `<div class="panel">${settingRow('Personal knowledge','Local Markdown vault · 24 pages · confirmed by you.',btn('Manage vault','connect-vault','folder','sm'))}${settingRow('Make this vault available in AI','Read access stays scoped to the granted folder.',toggle('vaultAI','Make vault available to AI',state.vaultAI!==false))}${settingRow('Session skills','Personal skills are discovered from the active AI profile.',btn('View skills','choose-skill:ask','automation','sm'))}${settingRow('Changes to knowledge','Review proposed edits before writing to your vault.',tag('Review first','green'))}</div>`;if(p.id==='scheduler')return `<div class="panel">${settingRow('Scheduled routines','Your prompt, selected profile, schedule and destination.',linkBtn('Open routines','automations.html','automation','sm'))}${settingRow('Background behavior','Routines run while the native host runs, including with its window closed.',tag('Native host required','amber'))}${settingRow('Delivery destinations','Today is local. Teams and mail need a connected Microsoft account.',linkBtn('Connections','settings-connections.html','link','sm'))}</div>`;if(p.id==='telegram')return `<div class="panel panel-pad"><h3>Your Telegram bot</h3><p class="small mt">The native app stores the bot token outside webview-visible settings. This demo never asks for a real token.</p><div class="notice mt">Bot: @workspace_demo_bot · ${state.telegramConfigured?'Connected in demo':'Not configured'}</div><div class="mt">${btn('Configure demo bot','configure-telegram','telegram','primary')}</div></div>`;return `<div class="panel panel-pad"><h3>No settings needed</h3><p class="small mt">Add this widget to Today, then customize your dashboard.</p><div class="mt">${btn('Add to Today','add-focus-widget','plus','primary')}</div></div>`}
pages['plugin-studio']=()=>`${head('Plugin studio','One package. Familiar services. Room for your own ideas.',`<a href="examples/focus-card.zip" download class="btn">${icon('download')}Download starter</a>`+btn('Validate manifest','validate-manifest','check','primary'))}<div class="two-column"><div class="stack"><div class="panel panel-pad"><div class="kicker accent">BUILD FOR YOUR OWN WORKSPACE</div><h2 style="font-size:24px;margin:12px 0">Bring an idea. Give it a place.</h2><p class="small">Add a Today widget, a dedicated page, a command, a knowledge view or a routine. Echo-format packages use the same host and client entry points in each compatible app.</p><div class="grid3 mt">${[['grid','Widgets','Use built-in stat, list, card, chart or page widgets.'],['code','Host services','Commands, timers, storage, network and granted files.'],['spark','AI & skills','Profile-routed Claude runs and package agent guidance.']].map(([i,t,d])=>`<div class="notice">${icon(i)}<h3 class="small" style="margin:9px 0 5px">${t}</h3>${d}</div>`).join('')}</div></div><div class="panel panel-pad"><div class="between mb"><h2>A small package, a clear contract</h2>${btn('Copy manifest','copy-manifest','copy','sm')}</div><pre class="codebox">${esc(JSON.stringify({id:'focus-card',name:'Focus card',version:'0.1.0',echo:'>=0.9.9',main:'main.js',agent:{summary:'Shows a local focus card in Today.'},widgets:[{id:'focus',label:'Focus card',kind:'card',sizes:['M']}],uses:{}},null,2))}</pre><div class="grid2 mt"><div><h3 class="small">Host · main.js</h3><pre class="codebox mt" style="margin-top:9px">export function apply(ctx) {
  ctx.widgets.provide('focus', () => ({
    title: 'Make room to think',
    text: 'One thing at a time.'
  }));
}</pre></div><div><h3 class="small">Package layout</h3><pre class="codebox mt" style="margin-top:9px">focus-card/
  echo-plugin.json
  main.js
  agent/
    CLAUDE.md</pre></div></div></div><div class="panel panel-pad"><h2>From idea to your workspace</h2>${[['Create a package','Use the starter, or keep an existing Echo package unchanged.'],['Declare what it needs','Name host services, network hosts, folders, skills and scripts in uses.'],['Validate in both hosts','Check the package, then test real host/client behavior with fictional fixtures.'],['Install locally','Review the access sheet; use a separate store for each app.'],['Publish when ready','Add it to echo-marketplace.json and publish a version. Permission changes need review.']].map(([t,d],i)=>`<div class="step"><span class="step-num">${i+1}</span><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div></div><aside class="stack">${panel('Native, with a contract',`<div style="padding:0 20px 20px"><p class="small">Echo packages run JavaScript inside a Rust host. They are not compiled Rust/Tauri plugins.</p><div class="line"></div><p class="small">Declared scripts can reach desktop tools with user rights. New privileged desktop services need an explicit host capability and OS-specific implementation.</p><div class="mt">${btn('See host capabilities','host-capabilities','monitor','sm')}</div></div>`,'','shield')}${panel('Compatibility checklist',`<div style="padding:0 20px 20px">${['Manifest & version rules','Complete host ctx contract','Client slots, CSS & helpers','Workspace data adapters','Profile & session routing','Permission and update diffs','macOS & Windows checks'].map(t=>`<div class="flex" style="padding:7px 0;font-size:11px;color:var(--text2)">${icon('clock')}${t}</div>`).join('')}<a class="text-link small" style="display:block;margin-top:14px" href="docs/PLUGIN-REUSE.md">Read the reuse plan ${icon('arrow')}</a></div>`,'','puzzle')}<div class="notice amber"><strong>Implementation gate</strong><br>Echo runtime: AGPL-3.0-only. Connect: Apache-2.0. Resolve the reuse and distribution path before copying runtime code. No Echo runtime code is included in this prototype.</div></aside></div>`;
